        self.log('STEP 6: configure interface port1.0.1 speed 1000 duplex full')
        # Provenance tag for this fragment: # legacy 5000_mdi_mdix/test-5000.0001-CopperFixed_Straight.py lines 328-404
        dut = self.testSet.dut
        port = dut.portA
        self.log('OPERATOR: configure interface port1.0.1 speed 1000 duplex full')
        want = 'connected'
        deadline = time.time() + 120
        output = ''
        while time.time() < deadline:
            output = dut.cmd('show interface {} status'.format(port), log=False)
            if want in output:
                break
            self.log('Waiting for operator: configure interface port1.0.1 speed 1000 duplex full')
            time.sleep(2)
        self.log('OBSERVED: {}'.format(output))
        
        show_int = dut.cmd('show interface {}'.format(port))
        if ('configured speed 1000' in show_int and 'configured duplex full' in show_int and
            'current speed 1000' in show_int and 'current duplex full' in show_int and
            'Link is UP' in show_int):
            self.passed("Prompt operator to physically remove and re-insert the cable/pluggable. Wait for link state transition. Run 'show interface port1.0.1' and assert 'configured speed 1000', 'configured duplex full', 'current speed 1000', 'current duplex full', and 'Link is UP' are retained.")
        else:
            self.failed("Prompt operator to physically remove and re-insert the cable/pluggable. Wait for link state transition. Run 'show interface port1.0.1' and assert 'configured speed 1000', 'configured duplex full', 'current speed 1000', 'current duplex full', and 'Link is UP' are retained.")

